/* Returns the Thruster Pack Lock Green moby in list idx whose bearing from a differs most from b's, or 0. */
void *find_thruster_pack_lock_green_moby_with_largest_xy_angle_in_list(float *a, float *b, int idx) {
    short *p = (short *)veldin2_moby_groups[idx];
    char *best = 0;
    float bestd = 0.0f;
    if (p == 0)
        return 0;
    while (1) {
        int off = (*p & 0x7FFF) << 8;
        if (*(short *)(off + (int)veldin2_moby_table_base.base + 0xA6) == 0x247) {
            float ang = fast_atan2(a[0] - b[0], a[1] - b[1]);
            L18Pos *m = (L18Pos *)(off + (int)veldin2_moby_table_base.base);
            float d = FastDiffRots(ang, fast_atan2(a[0] - m->x, a[1] - m->y));
            if (bestd < d) {
                bestd = d;
                best = veldin2_moby_table_m + off;
            }
        }
        if (*p++ < 0)
            return best;
    }
}

/* Of the Thruster Pack Lock Green mobys in list idx, the one nearest to pos (within
   255 units), or 0. The second spelling of the table base keeps the
   address out of the loop's $gp-relative reload in the bc1f delay slot. */
char *find_nearest_thruster_pack_lock_green_moby_in_list(void *pos, int idx) {
    short *p = (short *)veldin2_moby_groups[idx];
    char *best = 0;
    float bestd = 255.0f;
    if (p == 0)
        return 0;
    while (1) {
        int off = (*p & 0x7FFF) << 8;
        struct Moby *m = (struct Moby *)((char *)(off + (int)veldin2_moby_table_m));
        if (m->oclass == MOBY_CLASS_THRUSTER_PACK_LOCK_GREEN) {
            float d = FastVecDist(pos, &m->pos);
            if (d < bestd) {
                bestd = d;
                best = veldin2_moby_table_m + off;
            }
        }
        if (*p++ < 0)
            return best;
    }
}

