/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l18/gameplay/entities/002a7220.c, FUN_L18_002d7b20. */
void thruster_pack_lock_red_update(struct Moby *moby) {
    struct ThrusterLockVars *data = (struct ThrusterLockVars *)moby->pvars;
    int index;

    switch (moby->state) {
        case 0:
            data->base_z = moby->pos.z;
            data->flags |= 8;
            if (data->raised != 0) {
                moby->state = 1;
                moby->scale = *(float *)((char *)moby->pclass + 0x24) * (red_thruster_lock_scale);
                return;
            }
            moby->state = 4;
            return;
        case 1:
        case 3:
            ApproachWithVelocity(&moby->pos.z, &data->z_vel, data->base_z + (red_thruster_lock_raised_height),
                                 g_frame_time_sq * 20.0f, g_frame_time_sq * 40.0f, g_frame_time * 20.0f);
            break;
        case 2:
            ApproachWithVelocity(&moby->pos.z, &data->z_vel, data->base_z + (red_thruster_lock_wait_height),
                                 g_frame_time_sq * 5.0f, g_frame_time_sq * 10.0f, g_frame_time * 20.0f);
            if (g_hero_r2.air_frames.s == 0 && g_hero_r2.ground_moby == moby &&
                g_hero_r2.state.current == HERO_STATE_RISE_THEN_FALL_WITH_AIRBORNE_HIT_QUERY) {
                moby->state = 3;
                Moby_PlaySound(0, 0, (int)moby);
                index = data->voice;
                if (index != -1) {
                    unsigned char *entry = (unsigned char *)voice_pool + index * 0x70;
                    if (*(struct Moby **)(entry + 0x88) == moby && entry[0x74] != 0)
                        Sound_StopSlot(index);
                }
                data->voice = -1;
            } else if (g_hero_r2.state.current != 0x72) {
                AddDrawCallback(draw_pulsing_timer_hud_r, moby);
                if (fast_dec_timer(&data->timer) != 0)
                    (*(unsigned int *)&drek_boss_camera_move_request) = 1;
            }
            break;
        case 4:
            if (g_hero_r2.air_frames.s == 0 && g_hero_r2.ground_moby == moby &&
                g_hero_r2.state.current == HERO_STATE_RISE_THEN_FALL_WITH_AIRBORNE_HIT_QUERY) {
                moby->state = 5;
                moby->command = 1;
                moby->pos.z -= 1.5f;
                if (g_current_level_index == LEVEL_VELDIN2)
                    menu_item_enabled_115 = 1;
            }
            if (vec_distance_xy(&moby->pos, &g_hero_r2.motion.pos) < 2.5f) {
                struct UsageStat *help = help_records;
                int one = 1;
                if ((help[0x2B02].level_mask & (one << g_current_level_index)) == 0) {
                    if (help[0x71].count != 0) {
                        if (scale_ticks((gameplay_event_frame_count)) - help[0x71].unk2 * 600 >
                                (int)((float)scale_ticks(0x12) * 60.0f) ||
                            help[0x71].unk2 * 600 == 0) {
                            Help_Request(0x2B02, 0x71);
                        } else if (scale_ticks((gameplay_event_frame_count)) / 600 > help[0x71].unk2) {
                            help[0x71].unk2 = scale_ticks((gameplay_event_frame_count)) / 600;
                        }
                    } else {
                        help[0x71].count++;
                        if (scale_ticks((gameplay_event_frame_count)) / 600 > help[0x71].unk2) {
                            help[0x71].unk2 = scale_ticks((gameplay_event_frame_count)) / 600;
                        }
                        help[0x71].level_mask = help[0x71].level_mask | (one << g_current_level_index) | 0x80000000;
                    }
                }
            }
            break;
        case 5:
            if (ApproachValue((float *)&moby->pos.z, data->base_z - 1.5f, 0.15f) != 0.0f)
                return;
            moby->state = 6;
            break;
    }
}

/* Activates a moby and starts an effect on it if none is playing. */
void request_thruster_pack_lock_red_wait(unsigned char *arg, int value) {
    struct ThrusterLockVars *data = (struct ThrusterLockVars *)((Moby *)arg)->pvars;
    if (((Moby *)arg)->state != 2) {
        ((Moby *)arg)->state = 2;
        data->timer = value;
    }
    if (!Sound_IsPlaying(arg, data->voice)) {
        data->voice = allocate_voice_for_group_entry(0x12, 0, arg);
    }
}

/* Deactivates a moby in state 2 and stops its sound/effect slot. */
void end_thruster_pack_lock_red_wait(unsigned char *arg) {
    int *data = ((int *)((Moby *)arg)->pvars);
    if (((Moby *)arg)->state == 2) {
        int idx;
        ((Moby *)arg)->state = 3;
        idx = data[0x70 / 4];
        if (idx != -1) {
            unsigned char *e = (unsigned char *)voice_pool + idx * 0x70;
            if (*(unsigned char **)(e + 0x88) == arg && e[0x74]) {
                Sound_StopSlot(idx);
            }
        }
        data[0x70 / 4] = -1;
    }
}
/* Moby state check: state 3 becomes 1 and returns 1; state 2 returns -1 when data+0x6C is zero; else 0. */
int poll_moby_state_and_rearm(char *moby) {
    unsigned char st = moby[0x20];
    struct ThrusterLockVars *data = (struct ThrusterLockVars *)((Moby *)moby)->pvars;
    if (st == 3) {
        moby[0x20] = 1;
        return 1;
    }
    if (st == 2) {
        if (data->timer == 0) {
            return -1;
        }
    }
    return 0;
}
