extern void update_drek_fight_missile_trail_and_queue_effects(char *moby);

/* State machine for the Drek Fight Missile moby: dispatches on moby state (0 init, 2 wander, 3 dive, 4 land). */
void drek_fight_missile_update(char *moby) {
    struct Moby *m = (struct Moby *)moby;
    struct DrekMissileVars *missile_vars = (struct DrekMissileVars *)m->pvars;
    if (m->state != 4) {
        m->rot.x = FastAddRots(m->rot.x, drek_missile_spin_speed * 0.017453292f * g_frame_time);
    }
    if (veldin2_cinematic_mode == 2 && veldin2_cinematic_step == 3) {
        DeleteMoby(moby);
        return;
    }
    switch (m->state) {
        case 0: {
            float a = g_frame_time_sq;
            float b = g_frame_time;
            missile_vars->z_accel = a * 10.0f;
            missile_vars->turn_max = b * 12.566371f;
            missile_vars->turn_accel = a * 3.1415927f;
            missile_vars->z_max = b * 10.0f;
            missile_vars->phase = random_angle_radians();
            m->draw_dist = 0xFF;
            qcopy(&missile_vars->home_x, &m->pos);
            missile_vars->home_z += 5.0f;
            missile_vars->home_z = ProbeGroundHeight((void *)&missile_vars->home_x, 0, 0.5f);
            select_drek_fight_missile_wander_target(moby, &missile_vars->wander_target);
            m->state = 1;
            m->flags |= 1;
            m->visible = 0;
            m->collision = 0;
            break;
        }
        case 2: {
            char *p = (char *)&missile_vars->wander_target;
            if (update_drek_fight_missile_wander_movement(moby, (float *)p)) {
                select_drek_fight_missile_wander_target(moby, p);
            }
            update_drek_fight_missile_trail_and_queue_effects(moby);
            if (random_integer_below(drek_missile_dive_odds)) {
                return;
            }
            m->state = 3;
            missile_vars->wander_vx = FastCos(m->rot.z) * (drek_missile_wander_speed * g_frame_time);
            missile_vars->wander_vy = FastSin(m->rot.z) * (drek_missile_wander_speed * g_frame_time);
            missile_vars->wander_vz = missile_vars->z_vel;
            *(int *)&missile_vars->blend = 0;
            break;
        }
        case 3: {
            float v[4];
            float w[4];
            FastVecSub(v, &missile_vars->home_x, (void *)&m->pos);
            vec_scale_to_length(v, v, drek_missile_dive_speed * g_frame_time);
            ApproachValue(&missile_vars->blend, 1.0f, g_frame_time);
            lerp_vector(v, &missile_vars->wander_vx, v, missile_vars->blend);
            FastVecAdd((void *)&m->pos, (void *)&m->pos, v);
            m->rot.z = fast_atan2(v[0], v[1]);
            m->rot.y = -fast_atan2(vec_length_xy(v), v[2]);
            vec_scale_to_length(w, (void *)&m->rot_row0, 1.0f);
            FastVecAdd(w, w, (void *)&m->pos);
            update_drek_fight_missile_trail_and_queue_effects(moby);
            if (w[2] < missile_vars->home_z) {
                float t;
                Moby_PlaySound(1, 0, (int)moby);
                m->state = 4;
                missile_vars->timer = scale_ticks(0x5A);
                t = missile_vars->home_z + 0.7f;
                if (m->pos.z < t) {
                    m->pos.z = t;
                }
            }
            break;
        }
        case 4: {
            float x = m->rot.y;
            if (x < 0.87266463f) {
                x = 0.87266463f;
            }
            step_angle_toward_target((float *)&m->rot.y, 0, x, g_frame_time * 12.566371f);
            if (fast_dec_timer(&missile_vars->timer)) {
                int i;
                char *pos = (char *)&m->pos;
                m->state = 2;
                missile_vars->trail_len = 0;
                spawn_explosion(missile_vars->owner, &veldin2_zero_vec, pos, 1.0f, 1.0f, 10, 3, 16, 1.5f, 0.5f, 9.0f,
                                1.0f, 2, 5.0f, 0, 0, -1, 0);
                qcopy(pos, veldin2_camera_pos);
                m->pos.z += 20.0f;
                for (i = 0; (float)i < 4.0f; i++) {
                    qcopy(((char *)missile_vars) + 0x10 + i * 16, pos);
                }
            } else {
                update_drek_fight_missile_trail_and_queue_effects(moby);
            }
            break;
        }
    }
}
/* Hands pos to every Drek Fight Missile moby of the group that waits in state 1 and points it at moby: 0 if one took
   it, 1 if none.
   Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l18/gameplay/vendor/002efb88.c, FUN_L18_002f0030. */
int activate_drek_fight_missiles_in_group(char *moby, int group, float *pos) {
    short *p = (short *)veldin2_moby_groups[group];
    int idle;
    int i;
    if (p == 0)
        return 1;
    idle = 1;
    while (1) {
        unsigned char *m = (unsigned char *)(((*p & 0x7FFF) << 8) + (int)veldin2_moby_table_m);
        if (((Moby *)m)->oclass == MOBY_CLASS_DREK_FIGHT_MISSILE && ((Moby *)m)->state == 1) {
            unsigned char *d = ((unsigned char *)((Moby *)m)->pvars);
            idle = 0;
            qcopy(&((struct Moby *)m)->pos, pos);
            i = 0;
            do {
                qcopy(d + 0x10 + i * 16, &((struct Moby *)m)->pos);
                i++;
            } while ((float)i < 4.0f);
            *(char **)&((struct DrekMissileVars *)d)->owner = moby;
            ((Moby *)m)->visible = 1;
            ((Moby *)m)->flags &= 0xFFFE;
            *(int *)&((Moby *)m)->collision = *(int *)(*(char **)&((struct Moby *)m)->pclass + 0x10);
            ((Moby *)m)->state = 2;
        }
        if (*p++ < 0)
            return idle;
    }
}
